  height: var(--cipher-size-icon-caption);
}
.inputGroup[data-stacked] {
  flex-direction: column;
  align-items: stretch;
}
.inputGroup > [data-slot="input-group-control"] {
  padding-inline: var(--cipher-field-inline);
}
.inputGroup > textarea[data-slot="input-group-control"] {
  padding-block: calc(
    (var(--cipher-size-control-sm) - var(--cipher-type-body-line-height)) / 2 -
      var(--cipher-size-control-border)
  );
}
.inputGroup > [data-slot="input-group-addon"][data-align^="inline-"] {
  align-self: center;
  padding-block: var(--cipher-space-control-slot-inset);
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-start"] {
  padding-inline-start: var(--cipher-field-inline);
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-end"] {
  padding-inline-end: var(--cipher-field-inline);
}
.inputGroup[data-addon-start] > [data-slot="input-group-control"] {
  padding-inline-start: var(--cipher-space-control-gap);
}
.inputGroup[data-addon-end] > [data-slot="input-group-control"] {
  padding-inline-end: var(--cipher-space-control-gap);
}
.trailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-control-slot-gap);
  --cipher-nested-action-height: var(--cipher-field-nested);
}
.trailing > :not([data-cipher-button]) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--cipher-nested-action-height);
  min-height: var(--cipher-nested-action-height);
}
.trailing > [data-cipher-button] {
  --cipher-action-height: min(
    var(--cipher-action-requested-height),
    var(--cipher-nested-action-height)
  );
}
.suggestion {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  cursor: pointer;
}
.bare:not(:placeholder-shown) ~ .trailing > .suggestion {
  display: none;
}
.switch[data-size] {
  border-radius: 0;
}
.switch > [data-slot="switch-thumb"] {
  border-radius: 0;
}
.progress,
.progressIndicator {
  border-radius: 0;
}
.label {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.supporting {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.body {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.rowTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.sectionTitle {
  font-family: var(--cipher-type-title-sm-font-family);
  font-size: var(--cipher-type-title-sm-font-size);
  line-height: var(--cipher-type-title-sm-line-height);
  font-weight: var(--cipher-type-title-sm-font-weight);
  letter-spacing: var(--cipher-type-title-sm-letter-spacing);
}
.technical {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.otp {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
}
.otpGroup {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-6);
}
.otpSlot[data-slot] {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--cipher-size-control-md);
  height: var(--cipher-size-control-md);
  border: var(--cipher-size-control-border) solid var(--cipher-control);
  border-radius: 0;
  background-color: var(--cipher-control-surface);
  color: var(--cipher-ink);
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.otpSlot[data-active="true"] {
  z-index: 1;
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.otp.otpInvalid .otpSlot[data-slot] {
  border-color: var(--cipher-control-invalid-border);
}
.otp.otpInvalid .otpSlot[data-active="true"] {
  border-color: var(--cipher-bad);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring-bad);
}
.otp.otpDisabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.otpSeparator {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  color: var(--cipher-muted);
}
.otpCaretBox {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.otpCaret {
  width: 1px;
  height: var(--cipher-size-icon);
  background: var(--cipher-ink);
  animation: otpCaret 1s steps(1, end) infinite;
}
@keyframes otpCaret {
  50% {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .otpCaret {
    animation: none;
  }
}
@container (max-width: 12rem) {
  .cardHeader:not([data-framed]) {
    grid-template-columns: minmax(0, 1fr);
    row-gap: var(--cipher-space-8);
  }
  .cardHeader:not([data-framed]) > .cardAction {
    grid-column: 1;
    grid-row: auto;
    justify-self: start;
    height: auto;
    margin-inline-start: var(--cipher-card-lead);
  }
}

.progressLabels {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}

.sliderTrack {
  border-radius: 0;
  background-color: var(--cipher-slider-track);
}
.sliderRange {
  background-color: var(--cipher-slider-range);
}
.sliderThumb[data-slot] {
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
  border: 2px solid var(--cipher-on-accent);
  border-radius: 0;
  background: var(--cipher-accent);
  box-shadow: 0 1px 2px color-mix(in oklab, var(--cipher-frame) 18%, transparent);
  transition-property: box-shadow;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-standard);
}
@media (hover: hover) {
  .sliderThumb[data-slot]:hover {
    box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
  }
}
.sliderThumb[data-slot]:focus-visible {
  outline: none;
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
[data-slot="slider"][data-disabled] .sliderRange {
  background-color: var(--cipher-faint);
}
[data-slot="slider"][data-disabled] .sliderThumb[data-slot] {
  border-color: var(--cipher-line-soft);
  background: var(--cipher-control-disabled-surface);
}
.skeleton {
  border-radius: 0;
}

.caption {
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
}

.card:is(
  [data-flush],
  [data-variant="framed"]:has(
    > .cardBody
      > :is([data-slot="data-table"], [data-slot="table-container"]):is(
        :only-child,
        [data-slot="card-toolbar"]:first-child + :last-child
      ),
    > .cardInset
      > .cardBody
      > :is([data-slot="data-table"], [data-slot="table-container"]):is(
        :only-child,
        [data-slot="card-toolbar"]:first-child + :last-child
      )
  )
) {
  --cipher-card-body-inset: 0px;
  --cipher-card-lead: 0px;
}
.card[data-flush] > .cardHeader {
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}

.toggle {
  border-style: solid;
  color: var(--cipher-muted);
}
.toggle:disabled {
  cursor: not-allowed;
}
.toggle.toggle.toggle.toggle:disabled {
  color: var(--cipher-faint);
}
.toggleOutline {
  border-color: var(--cipher-action-outline-border);
  background-color: var(--cipher-action-outline-surface);
}
.toggleGhost {
  border-color: transparent;
  background-color: transparent;
}
@media (hover: hover) {
  .toggle:hover:not(:disabled, [aria-pressed="true"], [data-state="on"]) {
    background-color: var(--cipher-action-outline-hover);
    color: var(--cipher-ink);
  }
}
.toggle:is([aria-invalid="true"]) {
  border-color: var(--cipher-control-invalid-border);
}
.toggleGroup {
  display: inline-flex;
  flex-shrink: 0;
  width: fit-content;
  max-width: 100%;
  align-items: center;
  gap: var(--cipher-toggle-group-gap, 0px);
}
.toggleGroup[data-orientation="vertical"] {
  flex-direction: column;
  align-items: stretch;
}
.toggleGroup[data-width="full"] {
  display: flex;
  width: 100%;
}
.toggleGroup[data-width="full"][data-orientation="horizontal"] > [data-slot="toggle-group-item"] {
  flex: 1 1 0;
}
.toggleGroup[data-spacing="0"] {
  padding: var(--cipher-space-2);
  gap: var(--cipher-space-2);
  background: var(--cipher-tint);
  border-radius: 0;
}
.toggleGroup[data-spacing="0"]:not([data-indicator], [data-bare]) {
  box-shadow: inset 0 0 0 var(--cipher-size-control-border) var(--cipher-line-soft);
}
.toggleGroup[data-spacing="0"][data-bare] {
  padding: 0;
  background: transparent;
  border-radius: 0;
}
.toggleGroup[data-spacing="0"][data-bare] > [data-slot="toggle-group-item"] {
  border-radius: 0;
}
.toggleGroup[data-spacing="0"] > [data-slot="toggle-group-item"] {
  --cipher-action-height: calc(var(--cipher-action-requested-height) - 2 * var(--cipher-space-2));
  border-color: transparent;
  background-color: transparent;
  box-shadow: none;
  border-radius: 0;
}
.toggleGroup[data-spacing="0"]:not([data-indicator])
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]),
.toggleGroup[data-spacing="0"]:not([data-indicator])
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]):hover {
  background-color: var(--cipher-pop);
  border-color: var(--cipher-line-soft);
  box-shadow: var(--cipher-shadow-raised);
  color: var(--cipher-ink);
}
:global(.cipher[data-scheme="dark"])
  .toggleGroup[data-spacing="0"]:not([data-indicator])
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]),
:global(.cipher[data-scheme="dark"])
  .toggleGroup[data-spacing="0"]:not([data-indicator])
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]):hover {
  background-color: var(--cipher-surface);
  border-color: var(--cipher-line);
  box-shadow: none;
}
.toggleGroup[data-indicator] {
  position: relative;
}
.toggleGroup[data-indicator] > [data-slot="toggle-group-item"] {
  position: relative;
}
.toggleGroup[data-indicator]
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]),
.toggleGroup[data-indicator]
  > [data-slot="toggle-group-item"].toggle:is([aria-pressed="true"], [data-state="on"]):hover {
  background-color: transparent;
  border-color: transparent;
  color: var(--cipher-ink);
}
@media (hover: hover) {
  .toggleGroup[data-spacing="0"]
    > [data-slot="toggle-group-item"]:hover:not(
      :disabled,
      [aria-pressed="true"],
      [data-state="on"]
    ) {
    background-color: var(--cipher-hover);
    color: var(--cipher-ink);
  }
}
.toggleGroup[data-spacing="0"]:not([data-bare]) > .indicator {
  border-radius: 0;
}
.indicator {
  position: absolute;
  top: 0;
  left: 0;
  box-sizing: border-box;
  pointer-events: none;
  background: var(--cipher-pop);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  box-shadow: var(--cipher-shadow-raised);
  border-radius: 0;
}
:global(.cipher[data-scheme="dark"]) .indicator {
  background: var(--cipher-surface);
  border-color: var(--cipher-line);
  box-shadow: none;
}
.groupText {
  display: inline-flex;
  align-self: stretch;
  align-items: center;
  gap: var(--cipher-space-control-gap);
  padding-inline: var(--cipher-space-control-inline-sm);
  border: var(--cipher-size-control-border) solid var(--cipher-action-outline-border);
  border-radius: 0;
  background-color: transparent;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
}
.groupText[data-size="xs"] {
  padding-inline: var(--cipher-space-6);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
}
.groupTextLabel {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.groupText:not(:has(> *)) {
  display: block;
  align-content: center;
  text-overflow: ellipsis;
}
.groupText svg {
  flex: none;
  width: var(--cipher-size-icon-label);
  height: var(--cipher-size-icon-label);
  pointer-events: none;
}
.groupText[data-size="xs"] svg {
  width: var(--cipher-size-icon-caption);
  height: var(--cipher-size-icon-caption);
}
.groupSeparator[data-slot="button-group-separator"] {
  flex: none;
  align-self: stretch;
  background-color: var(--cipher-line-soft);
}
.groupSeparator[data-orientation="vertical"] {
  width: var(--cipher-size-control-border);
  height: auto;
  margin-block: var(--cipher-space-6);
}
.groupSeparator[data-orientation="horizontal"] {
  height: var(--cipher-size-control-border);
  width: auto;
  margin-inline: var(--cipher-space-6);
}
.group[data-variant="toolbar"] > .groupSeparator {
  margin-inline: var(--cipher-space-4);
}
.group > .groupSeparator[data-between-outlines] {
  display: none;
}
.card[data-variant="framed"] > .cardInset,
.card[data-variant="framed"] > .cardBody:not([data-before-footer]),
.card[data-variant="framed"] > .cardFooter:not([data-placement="frame"]) {
  box-shadow: var(--cipher-shadow-card-inset);
}

.wide[data-slot="popover-content"] {
  width: max-content;
  max-width: var(--radix-popper-available-width, 100vw);
}
.panel {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-12);
}
.presets {
  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: var(--cipher-space-2);
  padding-inline-end: var(--cipher-space-12);
  border-inline-end: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.main {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-8);
  width: min-content;
}
.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-size-control-xs);
  padding-block-start: var(--cipher-space-8);
  border-block-start: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.actions {
  display: flex;
  margin-inline-start: auto;
  align-items: center;
  gap: var(--cipher-space-8);
}
.times {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--cipher-space-8);
}
.time {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
  min-width: 0;
}
.time input::-webkit-calendar-picker-indicator {
  display: none;
}
.status {
  flex: 1 0 100%;
  contain: inline-size;
  color: var(--cipher-muted);
}
@media (max-width: 47.99rem) {
  .panel {
    flex-direction: column;
    align-items: stretch;
  }
  .presets {
    flex-direction: row;
    flex-wrap: wrap;
    padding-inline-end: 0;
    padding-block-end: var(--cipher-space-12);
    border-inline-end: none;
    border-block-end: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  }
}
